
module LiteFast(clk_tx_i,
                rst_n_tx_i,
                min_remote_token_tx_i,
                simplex_en_i,
                local_rece_rdy_tx_i,
                usr_data_rdy_tx_i,
                usr_data_tx_i,
                usr_data_val_tx_i,
                req_usr_data_tx_o,
                local_token_tx_i,
                remote_token_tx_i,
                crc_err_en_tx_i,
                LiteFast_k_tx_o,
                LiteFast_data_tx_o,
                clk_rx_i,
                rst_n_rx_i,
                serdes_rx_val_i,
                word_aligned_rx_i,
                lane_k_rx_i,
                lane_data_rx_i,
                block_aligned_rx_o,
                lane_aligned_rx_o,
                remote_token_rx_o,
                crc_err_rx_o,
                usr_data_val_rx_o,
                usr_data_rx_o);
  /****************************************************************************************/
  /*****************    supported working mode :                         ******************/
  /*****************    g_DATA_WID could be 8,16,32,64                   ******************/
  /*****************    g_DATA_WID = 8 : g_LANE_NUM must be 1            ******************/
  /*****************    g_DATA_WID = 16: g_LANE_NUM could be 1 or 2      ******************/
  /*****************    g_DATA_WID = 32: g_LANE_NUM could be 1 or 2 or 4      ******************/
  /*****************    g_DATA_WID = 64: g_LANE_NUM must be 2 or 4            ******************/
  /****************************************************************************************/
  /****************************************************************************************/
  /**************************    Parameters  **********************************************/
  /****************************************************************************************/
  parameter g_DATA_WID = 8;
  parameter g_LANE_NUM = 1;
  //LiteFast_Mode : (0), TX&RX  (1), RX only   (2),TX only
  parameter LiteFast_Mode = 0;


  /****************************************************************************************/
  /***************************      Input and Output Ports    *****************************/
  /****************************************************************************************/
  input clk_tx_i;
  input rst_n_tx_i;
  input[7 : 0] min_remote_token_tx_i;
  input simplex_en_i;
  input local_rece_rdy_tx_i;
  input[7 : 0] local_token_tx_i;
  input[7 : 0] remote_token_tx_i;
  input crc_err_en_tx_i;
  input usr_data_rdy_tx_i;
  input usr_data_val_tx_i;
  input[g_DATA_WID - 1 : 0] usr_data_tx_i;
  output req_usr_data_tx_o;
  output[(g_DATA_WID / 8) - 1 : 0] LiteFast_k_tx_o;
  output[g_DATA_WID - 1 : 0] LiteFast_data_tx_o;
  input clk_rx_i;
  input rst_n_rx_i;
  input[g_LANE_NUM - 1 : 0] serdes_rx_val_i;
  input[g_LANE_NUM - 1 : 0] word_aligned_rx_i;
  input[(g_DATA_WID / 8) - 1 : 0] lane_k_rx_i;
  input[g_DATA_WID - 1 : 0] lane_data_rx_i;
  output lane_aligned_rx_o;
  output[7 : 0] remote_token_rx_o;
  output crc_err_rx_o;
  output usr_data_val_rx_o;
  output[g_DATA_WID - 1 : 0] usr_data_rx_o;
  output[g_LANE_NUM - 1 : 0] block_aligned_rx_o;

